import{_ as d,o as e,c as a,a2 as r}from"./chunks/framework.1lR7qgqY.js";const u=JSON.parse('{"title":"授權速查","description":"","frontmatter":{},"headers":[],"relativePath":"ref/licenses.md","filePath":"ref/licenses.md","lastUpdated":1793014002000}'),n={name:"ref/licenses.md"};function i(o,t,s,c,l,h){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="授權速查" tabindex="-1">授權速查 <a class="header-anchor" href="#授權速查" aria-label="Permalink to &quot;授權速查&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">使用前請先看</p><p>授權條款會改版 (Dify, MinerU, LobeHub 都曾改過), 以下為 2026-10-26 研究整理, 對外提供服務前請以各專案儲存庫的授權檔為準. 個人與內部使用通常不受影響 (信心: 中). 本頁不構成法律意見, 如有疑義請洽法律顧問.</p></div><h2 id="osi-開源與「原始碼公開」" tabindex="-1">OSI 開源與「原始碼公開」 <a class="header-anchor" href="#osi-開源與「原始碼公開」" aria-label="Permalink to &quot;OSI 開源與「原始碼公開」&quot;">​</a></h2><p>OSI (Open Source Initiative) 定義的開源授權不得對使用方式設限. 授權對使用方式有限制者, 原始碼雖然公開, 但不屬於 OSI 開源. 以 n8n 為例, 官方文件 (docs.n8n.io) 自述 &quot;according to the Open Source Initiative (OSI), open source licenses can&#39;t include limitations on use, so we do not call ourselves open source&quot;.</p><p>本手冊對這類專案稱「原始碼公開」, 不稱「開源」.</p><h2 id="軟體授權" tabindex="-1">軟體授權 <a class="header-anchor" href="#軟體授權" aria-label="Permalink to &quot;軟體授權&quot;">​</a></h2><table tabindex="0"><thead><tr><th>專案</th><th>授權</th><th>OSI 開源</th><th>對外提供服務時的重點</th></tr></thead><tbody><tr><td>Open WebUI</td><td>BSD-3 加品牌條款</td><td>否</td><td>品牌條款限制修改或移除標示</td></tr><tr><td>LibreChat</td><td>MIT (管理面板為 AGPL)</td><td>是</td><td>管理面板的 AGPL 條款須另行留意</td></tr><tr><td>AnythingLLM</td><td>MIT</td><td>是</td><td>-</td></tr><tr><td>LobeHub (原 LobeChat)</td><td>LobeHub Community License</td><td>否</td><td>散布修改後的衍生作品須商業授權, 不適合手冊建議改作</td></tr><tr><td>LiteLLM</td><td>MIT, <code>enterprise/</code> 目錄另有授權</td><td>部分</td><td>SSO 等功能屬企業版</td></tr><tr><td>LangGraph 程式庫</td><td>MIT</td><td>是</td><td>官方 Agent Server 在正式環境須授權金鑰</td></tr><tr><td>Langflow</td><td>MIT</td><td>是</td><td>-</td></tr><tr><td>n8n</td><td>Sustainable Use License 與 Enterprise License</td><td>否</td><td>官方自述非開源</td></tr><tr><td>Flowise</td><td>Apache 2.0 (企業目錄另計, 未驗證)</td><td>是</td><td>-</td></tr><tr><td>Dify</td><td>Dify Open Source License (以 Apache 2.0 修改)</td><td>否</td><td>未經書面授權不得營運多租戶服務; 不得移除標誌</td></tr><tr><td>MinerU</td><td>3.1.0 起自訂授權</td><td>否</td><td>月活躍使用者超過 1 億或月營收超過 2,000 萬美元須另取商業授權; 線上服務須標示</td></tr><tr><td>Docling</td><td>MIT</td><td>是</td><td>-</td></tr><tr><td>Qdrant</td><td>Apache 2.0</td><td>是</td><td>-</td></tr><tr><td>Arize Phoenix</td><td>Elastic License 2.0</td><td>否</td><td>-</td></tr><tr><td>promptfoo</td><td>MIT</td><td>是</td><td>所有權已變動, 見版本頁</td></tr><tr><td>Langfuse</td><td>MIT</td><td>是</td><td>-</td></tr><tr><td>llama-swap, pgvector, sqlite-vec</td><td>待核對</td><td>-</td><td>訓練資料內資訊, 可能已過時</td></tr></tbody></table><h2 id="模型授權" tabindex="-1">模型授權 <a class="header-anchor" href="#模型授權" aria-label="Permalink to &quot;模型授權&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模型</th><th>授權</th><th>備註</th></tr></thead><tbody><tr><td>Llama 系列 (含 Prompt Guard 2, Llama Guard 4)</td><td>Llama 4 Community License</td><td>須申請下載</td></tr><tr><td>Qwen3-Embedding</td><td>Apache 2.0</td><td>來源: 研究 2</td></tr><tr><td>EmbeddingGemma</td><td>Gemma 條款</td><td>-</td></tr></tbody></table><p>其餘模型授權於 K4 整理, 該章尚在撰寫中.</p><h2 id="授權疊加" tabindex="-1">授權疊加 <a class="header-anchor" href="#授權疊加" aria-label="Permalink to &quot;授權疊加&quot;">​</a></h2><p>組合多個元件後再對外提供服務時, 最嚴格的條款決定能做什麼 (信心: 中). 原始碼公開但非 OSI 開源的元件清單: Open WebUI, Dify, LobeHub, MinerU, Arize Phoenix, n8n; 模型端另有 Llama 4 Community License.</p>',12)])])}const b=d(n,[["render",i]]);export{u as __pageData,b as default};
